window.__posterData({"id": "lina-persson", "name": "Lina Persson", "folder": "Week44_VibeCodedPoster_LinaPersson", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// MIN KOMMENTAR:\n// STEG 1\n// Efter att AI refaktorerat koden (fast med samma funktion) gick den från ca 75 rader till 99 rader kod. Den största förändingen var att AI gjorde många variabler, eller const i detta fall, för olika värden för att lätt kunna ändra dessa på samma ställe. Exempelvis gjorde den const för fyllnadsfärg och linjetjocklek, vilket jag innan hade skrivit in manuellt i vid den relevanta delen av koden. För ett inte så omfattande projekt känns dock detta lite onödigt, med tanke på att dessa inställningar endast dyker upp en gång. De hade lika gärna kunnat stå i den relevanta delen av koden, vid själva funktionen, istället för att ropas in genom olika const. \n\n// ---------- Constants ----------\nconst CANVAS_W = 600;\nconst CANVAS_H = 800;\nconst CENTER_X = CANVAS_W / 2;\nconst CENTER_Y = CANVAS_H / 2;\n\nconst SLOW_FRAME_RATE = 5;\nconst FAST_FRAME_RATE = 15;\n\nconst OUTER_DIAMETER = 1100; // diameter of the outermost circle\nconst MIN_DIAMETER = 500;    // the circles stop shrinking at this diameter\nconst RECORD_FILL = [255, 105, 180];\nconst RING_WEIGHT = 10;\n\nconst STROKE_COLORS = ['#45031d', '#1e010b', '#85001b', '#70006c', '#9e4a00'];\n\n\n// MIN KOMMENTAR\n// STEG 2\n// Const för en funktion som jag gav ville skapa med hjälp av instruktioner till AI. Läs mer om det i min kommentar nedan, \"STEG 2 fortsättning\".\n// Circular text\nconst PRESENTER_TEXT = 'Lina Persson Presents  •  ';\nconst PRESENTER_REPEATS = 3;           // how many times the phrase repeats around the circle\nconst PRESENTER_DIAMETER = 700;        // diameter of the circle the text follows\nconst PRESENTER_SIZE = 44;             // bigger than before (was 18), but smaller than DISCO RAVE (120)\nconst PRESENTER_SPIN_SPEED = 0.1;      // radians per frame, so it spins faster when frameRate increases\n\n\n\n// MIN KOMMENTAR\n// STEG 3\n// Jag bad AI att addera ett eget element till koden som passade temat och fick då detta. AI valde att lägga till en laser show med laserstrålar som åker fram och tillbaks. Lasern bidrar till en rave-känsla och får således estetiskt i linje med projektets givna tema. Däremot krockar det lite med den originella posterns disco-estetik. Laserstrålarna upplevs som något \"påklistrade\" på postern snarare än integrerade i helheten, vilket skulle kunna bero på att AI fick instruktionen att bara lägga till ett element. \n// Dessutom har lasern och den snurrande vinylskivan ungefär lika stor visuell tygnd och tar på så sätt \"ut varandra\". Resultatet blir visserligen mer energifyllt, men känns rörigt och inte helt genomtänkt. \n// AI:s förslag bidrar inte riktigt heller till någon betydande interaktivitet eller något överraskande element. Enligt koden verkar det exempelvis som att musens x-position ska förändra ljusstrålarna, men detta märks inte i praktiken. \n// Sammanfattningsvis belyser detta att AI behöver mer specifika och tydliga instruktioner för att göra kreativa ändringar som faktiskt integreras väl i helheten och i det syfte som designen ämnar att uppfylla. \n\n// Laser show\nconst LASER_COLORS = ['#ff00ff', '#00ffff', '#39ff14', '#ff2079', '#ffee00']; // neon palette\nconst LASER_LENGTH = 1200;             // long enough to cross the whole poster\nconst LASER_BEAMS_NORMAL = 3;          // beams per emitter normally\nconst LASER_BEAMS_OVERDRIVE = 6;       // beams per emitter while the mouse is held\nconst LASER_SWEEP = 0.5;               // how far (radians) each beam swings from its base angle\nconst LASER_SPEED = 0.35;              // sweep speed per frame\nconst LASER_FLICKER_CHANCE = 0.1;      // chance that a beam blinks out for one frame\nconst LASER_STEER = 0.6;               // how much the mouse's X position tilts the beams\n\n// Each emitter sits in a corner and aims toward the middle of the poster\nconst LASER_EMITTERS = [\n  { x: 0,        y: 0,        base:  Math.PI / 4,       dir:  1 },\n  { x: CANVAS_W, y: 0,        base:  3 * Math.PI / 4,   dir: -1 },\n  { x: 0,        y: CANVAS_H, base: -Math.PI / 4,       dir: -1 },\n  { x: CANVAS_W, y: CANVAS_H, base: -3 * Math.PI / 4,   dir:  1 },\n];\n\n// ---------- Assets ----------\nlet imgVinylarm;\nlet imgBoll;\nlet discoFont;\n\nasync function setup() {\n  imgVinylarm = await loadImage('vinylarm.png');\n  imgBoll = await loadImage('boll.png');\n  discoFont = await loadFont('Daffiys.ttf');\n\n  createCanvas(CANVAS_W, CANVAS_H);\n  frameRate(SLOW_FRAME_RATE);\n}\n\n// ---------- Helpers ----------\n\n// MIN KOMMENTAR\n// STEG 1 fortsättning\n// Vi refaktoreringen valde också AI:n att skapa fler funktioner och att rita upp dessa i en main draw funktion. Detta gör förmodligen koden mer effektiv eftersom denkan ropa in en funktion flera gånger i stället för att manuellt skriva ut den. Detta vore dock viktigare för större projekt där funktioner återkommer många gåner, till skillnad från denna poster där de flesta elementen endast dyker upp en gång. \n// Jag såg också att AI delade upp koden tydligare i olika sektioner av tex variabler och funktioner, medan jag kodade i en mer kronologisk ordning utefter mitt arbetssätt. AI:s struktur gör koden lite mer logisk och enklare att navigera.\n\n// Random green shade: low red and blue values keep it in a green spectrum\nfunction randomGreen() {\n  return color(random(44, 81), random(100, 255), random(2, 5));\n}\n\n// Concentric circles with slightly random sizes and stroke colors,\n// which gives the effect of a spinning record (inspired by Austin's \"Thursday while loop\")\nfunction drawRecord() {\n  let diameter = OUTER_DIAMETER;\n\n  while (diameter > MIN_DIAMETER) {\n    circle(CENTER_X, CENTER_Y, diameter);\n    diameter -= random(10, 30);\n    fill(...RECORD_FILL);\n    stroke(random(STROKE_COLORS)); // random() picks a random array element\n    strokeWeight(RING_WEIGHT);\n  }\n}\n\n// MIN KOMMENTAR\n// STEG 2 fortsättning\n// I steg två bad jag AI att göra följande: “From that code, move the \"Persson presents\" text away from the middle and instead place it so that its spinning in a circle clockwise, with a diameter of about 700 pixels. The text should be bigger and more prominent than it is now, but the main text disco rave should still have the major focus. Everything else should be exatcly the same and the text should go behind the vinylarm picture “ \n// Detta gav mig det resultat jag ville ha, förutom att texten inte längre var centrerad. Jag fick således be AI att skriva om sin kod och rätta till felet. I detta steg uppstod också kod som jag med min nuvarande kunskapnivå inte riktigt förstår, tex \"char\".\n\n\n// Text placed along a circle that rotates clockwise.\n// The letter spacing is stretched slightly so the repeated phrase\n// fits the full circle with no visible seam.\n// Everything is wrapped in push/pop so its style settings don't leak out.\nfunction drawPresenter() {\n  push();\n  strokeWeight(0);\n  textAlign(CENTER);\n  textSize(PRESENTER_SIZE);\n  fill(randomGreen());\n\n  const radius = PRESENTER_DIAMETER / 2;\n  const chars = PRESENTER_TEXT.repeat(PRESENTER_REPEATS).split('');\n\n  // Total angle the letters take up, and the extra spacing needed to fill 360°\n  const totalAngle = chars.reduce((sum, ch) => sum + textWidth(ch) / radius, 0);\n  const extraPerChar = (TWO_PI - totalAngle) / chars.length;\n\n  translate(CENTER_X, CENTER_Y);\n  rotate(frameCount * PRESENTER_SPIN_SPEED); // increasing angle = clockwise\n\n  for (const ch of chars) {\n    const halfStep = (textWidth(ch) / radius + extraPerChar) / 2;\n    rotate(halfStep);\n    text(ch, 0, -radius); // letter sits on top of the circle, pointing outward\n    rotate(halfStep);\n  }\n  pop();\n}\n\n// Neon laser beams fanning out from the four corners.\n// - Sweep speed is tied to frameCount, so it speeds up with the frame rate\n// - Moving the mouse left/right tilts all the beams\n// - Holding the mouse switches to \"overdrive\" with twice as many beams\n// - ADD blending makes crossing beams glow brighter where they overlap\nfunction drawLasers() {\n  const beams = mouseIsPressed ? LASER_BEAMS_OVERDRIVE : LASER_BEAMS_NORMAL;\n  const steer = (mouseX / CANVAS_W - 0.5) * LASER_STEER;\n  const gap = 0.16; // angle between beams in the same fan\n\n  push();\n  blendMode(ADD);\n  strokeCap(ROUND);\n  noFill();\n\n  LASER_EMITTERS.forEach((emitter, e) => {\n    // Each emitter has its own phase so the fans never move in sync\n    const sweep = sin(frameCount * LASER_SPEED * emitter.dir + e * 1.7) * LASER_SWEEP;\n\n    for (let i = 0; i < beams; i++) {\n      if (random() < LASER_FLICKER_CHANCE) continue; // beam blinks out for a frame\n\n      const offset = (i - (beams - 1) / 2) * gap;\n      const angle = emitter.base + sweep + offset + steer * emitter.dir;\n      const endX = emitter.x + cos(angle) * LASER_LENGTH;\n      const endY = emitter.y + sin(angle) * LASER_LENGTH;\n\n      // Each beam keeps its color for a few frames, then moves on to the next neon color\n      const beamColor = color(LASER_COLORS[(i + e + floor(frameCount / 3)) % LASER_COLORS.length]);\n\n      // Three passes (wide and faint -> thin and bright) fake a glow\n      const passes = [[14, 40], [6, 90], [2, 255]];\n      for (const [weight, alpha] of passes) {\n        beamColor.setAlpha(alpha);\n        stroke(beamColor);\n        strokeWeight(weight);\n        line(emitter.x, emitter.y, endX, endY);\n      }\n    }\n  });\n  pop();\n}\n\nfunction drawDiscoBall() {\n  image(imgBoll, 50, 140, 500, 500);\n}\n\nfunction drawTitle() {\n  // push/pop isolate these style changes from the rest of the drawing\n  push();\n  strokeWeight(0);\n  textAlign(CENTER); // set explicitly so the title is always centered\n  textWeight(900);\n  textFont(discoFont);\n  textSize(120);\n  fill(randomGreen());\n  text('DISCO', CENTER_X, 400);\n  text('RAVE', CENTER_X, 500);\n  pop();\n}\n\nfunction drawTonearm() {\n  image(imgVinylarm, -100, 70, 1000, 1000);\n}\n\n// ---------- Main loop ----------\n// Layers are drawn from bottom to top\nfunction draw() {\n  drawRecord();\n  drawPresenter();\n  drawLasers(); // light show over the record, but behind the title\n\n  // Holding the mouse down shows the disco ball and speeds up the circles\n  if (mouseIsPressed) {\n    drawDiscoBall();\n    frameRate(FAST_FRAME_RATE);\n  }\n\n  drawTitle();\n  drawTonearm(); // topmost layer\n}\n\n// Double-click clears everything and resets the speed\nfunction doubleClicked() {\n  clear();\n  frameRate(SLOW_FRAME_RATE);\n}", "assets": {"Daffiys.ttf": {"mime": "font/ttf", "b64": ""}, "boll.png": {"mime": "image/webp", "b64": ""}, "vinylarm.png": {"mime": "image/webp", "b64": ""}}});
